import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {execFile} from 'node:child_process';
import {replayDecision} from '../decision-replay.mjs';
import {deterministicStateHash} from '../../../packages/game-engine/src/index.ts';
import {encodeState,legalActionMap,transition} from '../../../packages/computer-player/src/index.ts';
import {commander,unit,makeState} from '../../../packages/game-engine/test/helpers/state-builders.mjs';

// Captured with the shipped b6c4 engine, rather than generated by the new rules.
const fixture=JSON.parse(readFileSync(new URL('./fixtures/legacy-rush-pass.json',import.meta.url)));
const warmup=JSON.parse(readFileSync(new URL('./fixtures/legacy-rush-warmup.json',import.meta.url)));
const bounded=operation=>operation();
const worker=(command,game)=>new Promise(resolve=>{
  const child=execFile(process.execPath,['--import','tsx','tools/ai-trainer/engine-worker.mjs'],{timeout:10000},(error,stdout)=>resolve({error,output:JSON.parse(stdout.trim())}));
  child.stdin.end(JSON.stringify({command,game,indices:[0,2],budgetMs:8000})+'\n');
});

test('archived rush Pass replays the exact old hash and policy slot without changing stored evidence',()=>{
  const {state,record}=structuredClone(fixture),raw=JSON.stringify(fixture);
  record.encoded=Array.from(encodeState(state));
  const withEncoding=JSON.stringify({state,record});
  const next=replayDecision(state,record,bounded);
  assert.equal(deterministicStateHash(next),fixture.record.afterHash);
  assert.equal(JSON.stringify({state,record}),withEncoding);
  assert.deepEqual(record.action,{type:'pass'});assert.ok(record.legal.includes(2800));
  assert.throws(()=>transition(state,record.action),/CONTINUATION_REQUIRED/,'live and newly submitted Pass stays illegal');
  const current={...record,action:{type:'end_turn'}};
  assert.equal(deterministicStateHash(replayDecision(state,current,bounded)),record.afterHash);
  assert.equal(JSON.stringify(fixture),raw,'captured provenance is unchanged');
});

test('legacy normalization preserves all before/after, controller, encoding and policy proof gates',()=>{
  const {state,record}=fixture;
  for(const corrupt of [
    value=>{value.beforeHash='altered';},value=>{value.afterHash='altered';},
    value=>{value.controller='P2';},value=>{value.encoded=[1];},
    value=>{value.legal=[2800];},value=>{value.policy=[{index:2800,probability:.5}];},
    value=>{value.action.actorId='A';},value=>{value.action.from={row:4,col:3};},
  ]) {const changed=structuredClone(record);corrupt(changed);assert.throws(()=>replayDecision(state,changed,bounded));}
});

test('partial archived legality still verifies the selected turn-control slot independently',()=>{
  const {state,record}=structuredClone(fixture);
  Object.assign(record,{legal:[2800],policy:[],policyMask:false,
    legality:{complete:false,indices:[2800],checked:1,unknown:1},
    fallback:{schemaVersion:2,reason:'legality-incomplete',selectionBasis:'model-policy',valueSource:'root-model',selectedActionSafety:'eligible',checkedEligibleCount:1,uncheckedCount:1,provenLosingCount:0}});
  assert.equal(deterministicStateHash(replayDecision(state,record,bounded)),record.afterHash);
  const changed=structuredClone(record);changed.afterHash='altered';assert.throws(()=>replayDecision(state,changed,bounded),/after-state/);
});

test('historical Pass never closes mandatory retreat, follow, or an unsupplied rush',()=>{
  const states=[
    makeState({pieces:[commander('C1','P1',0,9),commander('C2','P2',9,0)],continuation:{type:'push',owner:'P2',attackerOwner:'P1',phase:'retreat',chainLength:1}}),
    makeState({pieces:[commander('C1','P1',0,9),commander('C2','P2',9,0),unit('A','P1',4,3)],continuation:{type:'push',owner:'P1',attackerOwner:'P1',phase:'follow',followPoint:{row:4,col:4},followGroupPieceIds:['A'],chainLength:1}}),
    makeState({pieces:[commander('C1','P1',3,6),commander('C2','P2',6,3),unit('A','P1',4,3),unit('B','P1',5,5),unit('E0','P2',0,4),unit('E1','P2',9,4),unit('E2','P2',4,2)],continuation:{type:'rush',owner:'P1',rushedPieceIds:['A'],rushChainPieceIds:['A'],chainLength:1}}),
  ];
  for(const state of states)assert.throws(()=>replayDecision(state,{action:{type:'pass'},controller:state.sideToMove,beforeHash:deterministicStateHash(state),afterHash:fixture.record.afterHash,legal:[...legalActionMap(state).keys()]},bounded),/CONTINUATION_REQUIRED/);
});

test('archived warmup replay and inventory preserve exact initial/final hashes and raw actions',async()=>{
  const game=structuredClone(warmup.game),raw=JSON.stringify(game);
  for(const command of ['replay','inventory']){
    const result=await worker(command,game);assert.equal(result.error,null);assert.equal(result.output.hash,game.finalHash);
    if(command==='inventory')assert.deepEqual(result.output.states.map(s=>s.hash),[game.decisions[0].beforeHash,game.decisions[2].beforeHash]);
  }
  assert.equal(JSON.stringify(game),raw);assert.deepEqual(game.warmupActions.at(-1),{type:'pass'});
  for(const key of ['initialState','finalHash']){
    const corrupted=structuredClone(game);
    if(key==='initialState')corrupted.initialState.turnIndex++;else corrupted.finalHash='altered';
    const result=await worker('replay',corrupted);assert.ok(result.error);assert.match(result.output.message,/warmup mismatch|final hash mismatch/);
  }
});
